);

-- Jenis dokumen: prefix nomor, tabel sumber, aturan approval (configurable)
create table apx_mbms_doc_types (
   doc_type          varchar2(10)  not null
  ,doc_name          varchar2(100) not null
  ,prefix            varchar2(10)  not null
  ,table_name        varchar2(128) not null
  ,pk_column         varchar2(128) not null
  ,number_column     varchar2(128) not null
  ,status_column     varchar2(128) default 'STATUS' not null
  ,amount_expr       varchar2(4000)
