  ,note              varchar2(1000)
  ,constraint apx_mbms_approvals_pk primary key (approval_id)
  ,constraint apx_mbms_approvals_ck1 check (status in ('PENDING', 'APPROVED', 'REJECTED', 'CANCELLED'))
  ,constraint apx_mbms_approvals_fk1 foreign key (doc_type) references apx_mbms_doc_types (doc_type)
